import Fluent
import Vapor
import Foundation

// MARK: - Chat Message Model

final class ChatMessageModel: Model, @unchecked Sendable {
    static let schema = "chat_messages"

    /// Generated by Postgres, so it increases with every insert.
    @ID(custom: "seq", generatedBy: .database)
    var id: Int?

    @Field(key: "room")
    var room: String

    @Field(key: "user_id")
    var userId: UUID

    /// The author's name when the message was sent.
    @Field(key: "username")
    var username: String

    @Field(key: "text")
    var text: String

    @Field(key: "client_id")
    var clientId: String

    @Field(key: "sent_at")
    var sentAt: Date

    init() { }

    init(room: String, author: ChatUser, text: String, clientId: String, sentAt: Date) {
        self.room = room
        self.userId = author.id
        self.username = author.username
        self.text = text
        self.clientId = clientId
        self.sentAt = sentAt
    }

    func toDomain() throws -> ChatMessage {
        ChatMessage(
            seq: try requireID(),
            room: room,
            author: ChatUser(id: userId, username: username),
            text: text,
            sentAt: sentAt,
            clientId: clientId
        )
    }
}

// MARK: - Chat Repository Implementation

final class ChatRepository: ChatRepositoryProtocol, @unchecked Sendable {
    private let database: any Database

    init(database: any Database) {
        self.database = database
    }

    func save(room: String, author: ChatUser, text: String, clientId: String) async throws -> (message: ChatMessage, isNew: Bool) {
        let model = ChatMessageModel(room: room, author: author, text: text, clientId: clientId, sentAt: Date())
        do {
            try await model.create(on: database)
            return (try model.toDomain(), true)
        } catch {
            // (user_id, client_id) is unique: this may be a resend of a message already stored.
            guard (error as? any DatabaseError)?.isConstraintFailure == true,
                  let existing = try await ChatMessageModel.query(on: database)
                      .filter(\.$userId == author.id)
                      .filter(\.$clientId == clientId)
                      .first() else { throw error }
            return (try existing.toDomain(), false)
        }
    }

    func history(room: String, after: Int?, before: Int?, limit: Int) async throws -> ChatHistory {
        var query = ChatMessageModel.query(on: database).filter(\.$room == room)
        if let after {
            query = query.filter(\.$id > after)
        }
        if let before {
            query = query.filter(\.$id < before)
        }
        // One extra row tells whether older messages were left out.
        let newestFirst = try await query.sort(\.$id, .descending).limit(limit + 1).all()
        return ChatHistory(
            messages: try newestFirst.prefix(limit).reversed().map { try $0.toDomain() },
            hasMore: newestFirst.count > limit
        )
    }
}
